def _utc(dt: datetime | None) -> datetime | None:
    """Thời gian không kèm múi giờ thì coi là UTC (tránh lỗi so sánh naive/aware)."""
    if dt is not None and dt.tzinfo is None:
        return dt.replace(tzinfo=timezone.utc)
    return dt

