def _canon(plate: str | None) -> str | None:
    """Chuẩn hóa biển người dùng gõ: '51f 12345' -> '51F-123.45'."""
    if not plate or not plate.strip():
        return None
    text, valid = normalize_plate(plate)
    return text if valid else plate.strip().upper()

